script:
frappe.ui.form.on("Case Interest", {
    refresh(frm) {
        if (
            frm.doc.status === "Interested" &&
            frappe.user.has_role("Customer")
        ) {
            frm.add_custom_button("Accept Case", () => {
                frappe.call({
                    method: "legal_management.api.create_case",
                    args: {
                        case_interest: frm.doc.name
                    },
                    callback(r) {
                        if (!r.exc) {
                            frappe.msgprint("Case created successfully");
                            frappe.set_route("Form", "Case", r.message.case);
                        }
                    }
                });
            });
        }
    }
});

frappe.ui.form.on("Case Request", {
    refresh(frm) {
        if (frm.doc.status === "New" && frappe.user.has_role("Lawyer")) {
            frm.add_custom_button("I'm Interested", () => {
                frappe.call({
                    method: "legal_management.api.create_case_interest",
                    args: {
                        case_request: frm.doc.name

                    },
                    callback(r) {
                        if (!r.exc) {
                            frappe.msgprint("Case Interest successfully recorded");
                            frappe.set_route("Form", "Case Interest", r.message.case);
                        }
                    }
                });
            });
        }
    }
});
